// ═════════ 組成章節 ═════════
const CHAPTERS = [
  ...VOCAB_UNITS.map((u, i) => ({
    key: `voc-${i + 1}`, s: 'voc', ch: i + 1, label: `第 ${i + 1} 關`, name: u.name, exam: 1, star: 4, src: u.src, words: u.words,
    goal: `學會這一關的 ${u.words.length} 個單字：看得懂、聽得出、拼得出來。（${u.src}）`,
    blocks: [
      [`單字（${u.words.length} 個）`, u.words.map(w => `**${w[0]}**　${w[1]}`)],
      ['例句', u.words.filter(w => w[2]).slice(0, 8).map(w => `${w[2]}（${w[3]}）`)],
    ],
    tip: '先按 🔊 聽，再自己唸一次，最後試著拼出來',
  })),
  ...GRAMMAR.map(g => ({ ...g, s: 'gra', label: `文法 ${g.ch}`, exam: 1, star: 5 })),
];
// 每一科的單元平均分配在 start～learnEnd，第一個單元今天開放、最後一個在 learnEnd 開放
(function assignDays() {
  const span = Math.round((new Date(PLAN.learnEnd) - new Date(PLAN.start)) / 86400000);
  for (const s of Object.keys(SUBJ)) {
    const list = CHAPTERS.filter(c => c.s === s);
    list.forEach((c, i) => {
      const d = new Date(PLAN.start + 'T00:00:00');
      d.setDate(d.getDate() + Math.round(i * span / Math.max(1, list.length - 1)));
      c.day = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    });
  }
})();
